package org.retrobridge.galaxyservices.s2;
import android.app.*;import android.content.*;import android.net.wifi.*;import android.os.*;import org.retrobridge.galaxyservices.Wire;
import java.io.*;import java.net.*;import java.security.*;import java.util.concurrent.*;import java.lang.reflect.*;
public final class LegacyService extends Service {
 static volatile LegacyService active;
 MmsRelay media;CameraBackup camera;LocationMirror location;RequestWifi fastWifi;YouTubeLocal youtube;DeviceLink lifecycle;ServerSocket server;volatile boolean stopping;org.retrobridge.galaxyservices.SocketWorkers pool=new org.retrobridge.galaxyservices.SocketWorkers();byte[] key;volatile String network;
 final Runnable notificationMode=new Runnable(){public void run(){updateForeground();}};
 boolean ownForeground;
 void updateForeground(){
  if(stopping)return;
  if(NotificationLinkService.managed()){if(ownForeground){stopForeground(true);ownForeground=false;}((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).cancel(1);return;}
  Notification n=new Notification(R.drawable.service_notification,"Galaxy Services",System.currentTimeMillis());n.setLatestEventInfo(this,"Galaxy Services","Pixel internet",PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class),0));startForeground(1,n);ownForeground=true;
 }
 void status(String s){try{Wire.writeFile(new File(getFilesDir(),"status.txt"),s.getBytes("UTF-8"));}catch(Exception ignored){}}
 public void onCreate(){super.onCreate();active=this;fastWifi=new RequestWifi(this);lifecycle=new DeviceLink(this);lifecycle.start();location=new LocationMirror(this);location.start();camera=new CameraBackup(this);camera.start();media=new MmsRelay(this);media.start();NotificationLinkService.attach(notificationMode);updateForeground();
  new Thread(new Runnable(){public void run(){try{key=Wire.unhex(new String(Wire.readFile(new File(getFilesDir(),"link.key")),"US-ASCII").trim());if(key.length!=32)throw new IOException("Pairing missing");network=new String(Wire.readFile(new File(getFilesDir(),"network.txt")),"UTF-8").trim();server=new ServerSocket();server.setReuseAddress(true);server.bind(new InetSocketAddress("127.0.0.1",Wire.LOCAL));try{setProxy(true);}catch(Exception waiting){status("Waiting for saved Wi-Fi");}youtube=new YouTubeLocal(LegacyService.this);new Thread(youtube,"youtube-local").start();status("Ready");while(!stopping){final Socket c=server.accept();try{pool.execute(c,new Runnable(){public void run(){forward(c);}});}catch(RejectedExecutionException e){Wire.close(c);}}}catch(Exception e){if(!stopping)status("Start: "+e.getClass().getSimpleName()+" "+e.getMessage());}}},"legacy-listener").start();
 }
 public int onStartCommand(Intent i,int f,int id){if(i!=null&&i.getBooleanExtra("media",false)&&media!=null)media.kick();if(i!=null&&i.getBooleanExtra("camera",false)&&camera!=null)camera.kick();if(i!=null&&i.getBooleanExtra("networkRetry",false)){lifecycle.rejoin();lifecycle.sync();}if(i!=null&&i.getBooleanExtra("calendarAudit",false))new Thread(new Runnable(){public void run(){CalendarAudit.run(LegacyService.this);}},"calendar-audit").start();if(i!=null&&i.getBooleanExtra("calendar",false))lifecycle.sync();if(i!=null&&i.getBooleanExtra("weatherProbe",false))new Thread(new Runnable(){public void run(){WeatherProbe.run(LegacyService.this);}},"weather-probe").start();if(i!=null&&i.hasExtra("band")){try{WifiManager w=(WifiManager)getSystemService(WIFI_SERVICE);int prior=(Integer)w.getClass().getMethod("getFrequencyBand").invoke(w);int wanted=i.getIntExtra("band",-1);if(wanted!=0&&wanted!=2)throw new IllegalArgumentException("Invalid band");if(!getSharedPreferences("settings",0).contains("originalBand"))getSharedPreferences("settings",0).edit().putInt("originalBand",prior).commit();w.getClass().getMethod("setFrequencyBand",int.class,boolean.class).invoke(w,wanted,false);Wire.writeFile(new File(getFilesDir(),"band.txt"),("Previous="+prior+" Requested="+wanted).getBytes("UTF-8"));}catch(Exception e){try{Wire.writeFile(new File(getFilesDir(),"band.txt"),(e.toString()+String.valueOf(e.getCause())).getBytes("UTF-8"));}catch(Exception ignored){}}}if(i!=null&&i.getBooleanExtra("probe",false))new Thread(new Runnable(){public void run(){Probe.run(LegacyService.this);}},"probe").start();return START_STICKY;}public IBinder onBind(Intent i){return null;}
 public void onDestroy(){stopping=true;if(active==this)active=null;NotificationLinkService.detach(notificationMode);if(ownForeground)stopForeground(true);lifecycle.stop();fastWifi.close();if(camera!=null)camera.close();if(media!=null)media.close();if(location!=null)location.close();if(youtube!=null)youtube.close();try{if(server!=null)server.close();if(!getSharedPreferences("settings",0).getBoolean("enabled",true))setProxy(false);}catch(Exception ignored){}pool.shutdownNow();super.onDestroy();}
 String gateway()throws Exception {
  WifiManager w=(WifiManager)getSystemService(WIFI_SERVICE);WifiInfo info=w.getConnectionInfo();String ssid=info.getSSID(),expected=network;
  if(ssid!=null&&ssid.length()>=2&&ssid.startsWith("\"")&&ssid.endsWith("\""))ssid=ssid.substring(1,ssid.length()-1);
  if(expected==null||!expected.equals(ssid)){
   try{Wire.writeFile(new File(getFilesDir(),"wifi-match.txt"),("Expected length="+(expected==null?-1:expected.length())+" observed length="+(ssid==null?-1:ssid.length())+" state="+info.getSupplicantState()+" networkId="+info.getNetworkId()).getBytes("UTF-8"));}catch(Exception ignored){}
   throw new IOException("Waiting for Pixel Wi-Fi");
  }
  int g=w.getDhcpInfo().gateway;if(g==0)throw new IOException("Waiting for Wi-Fi address");return (g&255)+"."+((g>>>8)&255)+"."+((g>>>16)&255)+"."+((g>>>24)&255);
 }
 void forward(Socket local){try{local.setSoTimeout(15000);forwardHeader(local,Wire.header(local.getInputStream()));}catch(Exception e){Wire.close(local);}}
 void forwardHeader(Socket local,byte[] h){Socket remote=null;boolean fast=false;try{String request=new String(h,"ISO-8859-1");int firstEnd=request.indexOf("\r\n");String first=request.substring(0,firstEnd);String localTarget=" http://127.0.0.1:8768/";if(first.contains(localTarget)){first=first.replace(localTarget," http://youtube.galaxy-services.invalid/");h=(first+request.substring(firstEnd)).getBytes("ISO-8859-1");}String[] ytRequest=first.split(" ");if(ytRequest.length==3&&ytRequest[1].startsWith("http://youtube.galaxy-services.invalid/feeds/api/")&&!ytRequest[0].equals("GET")&&!ytRequest[0].equals("HEAD")){java.net.URI actionUri=new java.net.URI(ytRequest[1]);String actionPath=actionUri.getRawPath()+(actionUri.getRawQuery()==null?"":"?"+actionUri.getRawQuery());YouTubeSecure.forward(this,local,ytRequest[0],actionPath,new String(h,"ISO-8859-1"));return;}if(first.contains("youtube.galaxy-services.invalid")&&(first.contains("/assets/")||first.contains("/get_480")||first.contains("/channel_fh264_getvideo")||first.contains("/exp_hd")||first.contains("/sabr"))){fastWifi.acquire();fast=true;}byte[] nonce=new byte[16];new SecureRandom().nextBytes(nonce);String prefix="GS1 "+System.currentTimeMillis()+" "+Wire.hex(nonce)+"\n";String auth=prefix.substring(0,prefix.length()-1)+" "+Wire.hex(Wire.mac(key,prefix,h))+"\r\n";
  remote=new Socket(java.net.Proxy.NO_PROXY);Wire.tune(remote);Wire.tune(local);remote.connect(new InetSocketAddress(gateway(),Wire.PORT),15000);remote.setSoTimeout(60000);local.setSoTimeout(60000);OutputStream out=remote.getOutputStream();out.write(auth.getBytes("US-ASCII"));out.write(h);out.flush();status("Connected");Wire.bridge(local,remote);
 }catch(Exception e){status("Connection: "+e.getClass().getSimpleName()+" "+e.getMessage());try{local.getOutputStream().write("HTTP/1.1 503 Service Unavailable\r\nConnection: close\r\nContent-Length: 0\r\n\r\n".getBytes("US-ASCII"));}catch(Exception ignored){}}finally{Wire.close(local);Wire.close(remote);if(fast)fastWifi.release();}}
 @SuppressWarnings({"rawtypes","unchecked"}) void setProxy(boolean enabled)throws Exception {
  WifiManager w=(WifiManager)getSystemService(WIFI_SERVICE);if(network==null)network=new String(Wire.readFile(new File(getFilesDir(),"network.txt")),"UTF-8").trim();
  java.util.List<WifiConfiguration> all=w.getConfiguredNetworks();if(all==null)throw new IOException("No saved Wi-Fi");
  for(WifiConfiguration old:all){if(!("\""+network+"\"").equals(old.SSID)&&!network.equals(old.SSID))continue;
   Class cls=Class.forName("android.net.wifi.WifiConfiguration$ProxySettings");Field proxy=WifiConfiguration.class.getField("proxySettings");Object prior=proxy.get(old);Object link=WifiConfiguration.class.getField("linkProperties").get(old);
   Class prop=Class.forName("android.net.ProxyProperties");Object existing=link.getClass().getMethod("getHttpProxy").invoke(link);boolean own=existing!=null&&"127.0.0.1".equals(prop.getMethod("getHost").invoke(existing))&&((Integer)prop.getMethod("getPort").invoke(existing))==Wire.LOCAL;
   if(enabled&&!prior.toString().equals("NONE")&&!prior.toString().equals("UNASSIGNED")&&!own)throw new IOException("Existing proxy retained");if(!enabled&&!own)return;
   if(enabled&&own)return;
   WifiConfiguration copy=WifiConfiguration.class.getConstructor(WifiConfiguration.class).newInstance(old);Object lp=WifiConfiguration.class.getField("linkProperties").get(copy);proxy.set(copy,Enum.valueOf(cls,enabled?"STATIC":"NONE"));
   Object value=enabled?prop.getConstructor(String.class,int.class,String.class).newInstance("127.0.0.1",Wire.LOCAL,""):null;lp.getClass().getMethod("setHttpProxy",prop).invoke(lp,value);
   if(w.updateNetwork(copy)<0||!w.saveConfiguration())throw new IOException("Wi-Fi proxy save failed");return;
  }throw new IOException("Pixel Wi-Fi not saved");
 }
}
